tr.lesson('osmanli-siyaset', 11, 'XVII. ve XVIII. yüzyıl Osmanlı siyaseti: Zitvatorok\'tan Küçük Kaynarca\'ya.', [
  TIMELINE(['1606', 'Zitvatorok Antlaşması (Avusturya)', 'Avusturya arşidükü Osmanlı padişahıyla eşit sayıldı; Osmanlı üstünlüğü sarsıldı.'], ['1639', 'Kasr-ı Şirin Antlaşması (İran)', 'Bugünkü Türkiye-İran sınırı büyük ölçüde belirlendi.'], ['1683', 'II. Viyana Kuşatması', 'Başarısızlık; Kutsal İttifak savaşları başladı.'], ['1699', 'Karlofça Antlaşması', 'İlk büyük toprak kaybı; duraklamadan gerilemeye.'], ['1711', 'Prut Antlaşması (Rusya)', 'Osmanlı\'nın Rusya karşısındaki son büyük başarısı.'], ['1718', 'Pasarofça Antlaşması', 'Lale Devri başladı.'], ['1739', 'Belgrad Antlaşması', 'Fransa\'nın arabuluculuğuyla Belgrad geri alındı.'], ['1774', 'Küçük Kaynarca Antlaşması', 'Kırım bağımsız; Rusya Ortodoksların hamisi oldu.']),
  TIP('Sınavda antlaşmaların hangi devletle yapıldığı sıkça sorulur: Zitvatorok – Avusturya, Kasr-ı Şirin – İran, Prut – Rusya, Küçük Kaynarca – Rusya.'),
  P('XVII. yüzyılda merkezî otoritenin zayıflaması, tımar sisteminin bozulması ve Celali isyanları duraklamaya yol açtı. IV. Murat ve Köprülüler dönemindeki sert ıslahatlar geçici başarı sağladı.'),
], [card('Kasr-ı Şirin (1639)', 'Türkiye-İran sınırı'), card('Zitvatorok (1606)', 'Avusturya ile eşitlik')]);
tr.q('osmanli-siyaset', 'Bugünkü Türkiye-İran sınırını büyük ölçüde belirleyen antlaşma aşağıdakilerden hangisidir?', ['Amasya', 'Kasr-ı Şirin', 'Zitvatorok', 'Nasuh Paşa', 'Serav'], 'B', '1639 Kasr-ı Şirin Antlaşması ile çizilen sınır büyük ölçüde günümüze kadar korunmuştur.', 1);
tr.q('osmanli-siyaset', 'Avusturya arşidükünün Osmanlı padişahıyla eşit sayıldığı antlaşma aşağıdakilerden hangisidir?', ['Zitvatorok', 'Karlofça', 'Pasarofça', 'Belgrad', 'İstanbul'], 'A', '1606 Zitvatorok Antlaşması ile Avusturya\'nın yıllık vergisi de kaldırıldı.', 1);
tr.q('osmanli-siyaset', 'Osmanlı Devleti\'nin Rusya ile imzaladığı ve Rusya karşısında elde ettiği son önemli başarı kabul edilen antlaşma aşağıdakilerden hangisidir?', ['Küçük Kaynarca', 'Prut', 'Yaş', 'Bükreş', 'Edirne'], 'B', '1711 Prut Savaşı\'nda kuşatılan Rus ordusu antlaşmayla kurtulabildi.', 2);

