tr.lesson('en-uzun-yuzyil', 11, 'Fransız İhtilali ve Sanayi İnkılabı\'nın Osmanlı\'ya etkileri; milliyetçilik, Boğazlar ve ekonomik sorunlar.', [
  UL('Fransız İhtilali (1789) milliyetçilik, özgürlük ve eşitlik fikirlerini yaydı; çok uluslu Osmanlı\'da isyanlar başladı. İlk isyan Sırp (1804), ilk bağımsızlığını kazanan millet Yunanlar oldu (1829 Edirne Antlaşması; 1830 bağımsızlık).', 'Sanayi İnkılabı (İngiltere, buhar makinesi) hammadde ve pazar arayışını, dolayısıyla sömürgeciliği artırdı.', 'Osmanlı ekonomisi: 1838 Balta Limanı Antlaşması yerli üretimi zayıflattı; ilk dış borç 1854\'te Kırım Savaşı sırasında alındı; 1881\'de Düyun-ı Umumiye kuruldu.'),
  TIMELINE(['1833', 'Hünkâr İskelesi Antlaşması', 'Rusya ile; Boğazlar Rus savaş gemilerine açık, diğerlerine kapalı.'], ['1841', 'Londra Boğazlar Sözleşmesi', 'Boğazlar barış zamanında tüm yabancı savaş gemilerine kapatıldı.'], ['1878', 'Berlin Antlaşması', 'Ermeni meselesi uluslararası gündeme girdi.']),
  TIP('Bu dönemi "dağılmayı önleme çabaları" olarak düşünün: ıslahatlar (Nizam-ı Cedit, Tanzimat), fikir akımları (Osmanlıcılık, İslamcılık, Türkçülük) ve denge politikası aynı amaca hizmet eder.'),
], [card('İlk bağımsızlık', 'Yunanistan (1829–1830)'), card('İlk dış borç', '1854 — Kırım Savaşı')]);
tr.q('en-uzun-yuzyil', 'Osmanlı Devleti\'nden ayrılarak bağımsızlığını kazanan ilk millet aşağıdakilerden hangisidir?', ['Sırplar', 'Yunanlar', 'Bulgarlar', 'Romenler', 'Arnavutlar'], 'B', 'İlk isyan eden Sırplar olsa da ilk bağımsızlığını kazanan Yunanlardır (1829 Edirne Antlaşması).', 2);
tr.q('en-uzun-yuzyil', 'Osmanlı Devleti ilk dış borcunu hangi yıl ve hangi gelişme sırasında almıştır?', ['1838 — Balta Limanı', '1854 — Kırım Savaşı', '1876 — I. Meşrutiyet', '1881 — Muharrem Kararnamesi', '1912 — Balkan Savaşları'], 'B', 'Kırım Savaşı\'nın masraflarını karşılamak için 1854\'te İngiltere\'den borç alındı.', 1);
tr.q('en-uzun-yuzyil', 'Boğazların barış zamanında bütün yabancı savaş gemilerine kapatıldığı uluslararası sözleşme aşağıdakilerden hangisidir?', ['Hünkâr İskelesi Antlaşması', 'Londra Boğazlar Sözleşmesi', 'Paris Antlaşması', 'Montrö Sözleşmesi', 'Lozan Antlaşması'], 'B', '1841 Londra Sözleşmesi ile Boğazlar ilk kez uluslararası bir statüye kavuştu.', 2);

